import os
import re
import subprocess
import sys

from .errors import ICaclsError

#: icacls 可执行文件名。
ICACLS = "icacls"

#: 只在目录上有意义的继承标志，不参与权限集合。
_INHERITANCE_FLAGS = frozenset({"OI", "CI", "IO", "NP"})

#: 「继承而来」标志。
_INHERITED_FLAG = "I"

#: 「拒绝」标志。
_DENY_FLAG = "DENY"

_ACE_RE = re.compile(r"^\s*(.+?):((?:\([^)]*\))+)\s*$")
_TOKEN_RE = re.compile(r"\(([^)]*)\)")
_SID_RE = re.compile(r"^S-\d+(?:-\d+)*$", re.IGNORECASE)

#: 主体标识 -> 等价标识集合的缓存（同一进程内主体解析结果不变）。
_PRINCIPAL_CACHE = {}
_PRINCIPAL_CACHE_LIMIT = 1024


