    """返回 ``path`` 的若干等价写法，用于识别 icacls 首行回显的路径。"""
    variants = []
    candidates = [path]
    try:
        candidates.append(os.path.normpath(path))
        candidates.append(os.path.abspath(path))
        candidates.append(os.path.normpath(os.path.abspath(path)))
    except (OSError, ValueError):
        pass
    for cand in candidates:
        if cand and cand not in variants:
            variants.append(cand)
    return variants


def _strip_path_prefix(principal, path):
    """把 icacls 首行里回显的路径从主体名前面去掉。

    ``icacls <path>`` 的第一行形如 ``<path> <principal>:(...)``，若不去掉
    路径前缀，第一条 ACE 的主体名就会被解析成「路径 + 主体」。
