    if not path or not principal:
        return None
    lowered = principal.lower()
    for cand in _path_variants(path):
        low_cand = cand.lower()
        if not lowered.startswith(low_cand):
            continue
        rest = principal[len(cand) :]
        # 路径与主体之间以空白分隔；只有确实剩下主体名时才替换。
        if rest[:1].isspace() and rest.strip():
            return rest.strip()
    return None


def _ace_indent(lines):
    """返回 icacls 输出中续行（不含路径前缀的行）的缩进宽度。

    icacls 会把后续 ACE 对齐到首行主体名的起始列，因此这个宽度正好等于
    首行里路径前缀的长度。
    """
    for line in lines:
        if line[:1].isspace() and _ACE_RE.match(line):
            return len(line) - len(line.lstrip())
    return 0


