    """把 ``"(OI)(CI)(DENY)(W,D)"`` 之类的片段拆成 (权限集合, 是否拒绝, 是否继承)。"""
    rights = set()
    deny = False
    inherited = False
    for token in _TOKEN_RE.findall(chunk):
        # 一个括号里可以用逗号并列多个权限，例如 ``(W,D)``、``(WD,AD)``。
        for part in token.split(","):
            part = part.strip().upper()
            if not part:
                continue
            if part == _DENY_FLAG:
                deny = True
            elif part == _INHERITED_FLAG:
                inherited = True
            elif part in _INHERITANCE_FLAGS:
                continue
            else:
                rights.add(part)
    return rights, deny, inherited


