    """把 icacls 的输出解析成 :class:`Ace` 列表。

    ``path`` 是被查询的路径（可选）。给出它可以正确解析首行——那一行以
    路径开头，紧跟着第一条 ACE 的主体名。
    """
    lines = output.splitlines()
    indent = _ace_indent(lines)
    aces = []
    for line in lines:
        m = _ACE_RE.match(line)
        if not m:
            continue
        principal = m.group(1).strip()
        if not line[:1].isspace():
            # 首行带路径前缀：优先按已知路径剥离，其次按续行对齐列剥离。
            stripped = _strip_path_prefix(principal, path)
            if stripped is None and indent and len(line) > indent:
                m2 = _ACE_RE.match(line[indent:])
                if m2:
                    stripped = m2.group(1).strip()
            if stripped:
                principal = stripped
        rights, deny, inherited = _parse_rights(m.group(2))
        if not rights:
            continue
        aces.append(Ace(principal, rights, deny=deny, inherited=inherited))
    return aces


