            part = part.strip().upper()
            if not part:
                continue
            if part == _DENY_FLAG:
                deny = True
            elif part == _INHERITED_FLAG:
                inherited = True
            elif part in _INHERITANCE_FLAGS:
                continue
            else:
                rights.add(part)
    return rights, deny, inherited


def parse_aces(output, path=None):
    """把 icacls 的输出解析成 :class:`Ace` 列表。

    ``path`` 是被查询的路径（可选）。给出它可以正确解析首行——那一行以
    路径开头，紧跟着第一条 ACE 的主体名。
    """
    lines = output.splitlines()
    indent = _ace_indent(lines)
    aces = []
    for line in lines:
        m = _ACE_RE.match(line)
        if not m:
            continue
        principal = m.group(1).strip()
        if not line[:1].isspace():
            # 首行带路径前缀：优先按已知路径剥离，其次按续行对齐列剥离。
            stripped = _strip_path_prefix(principal, path)
            if stripped is None and indent and len(line) > indent:
                m2 = _ACE_RE.match(line[indent:])
                if m2:
                    stripped = m2.group(1).strip()
            if stripped:
                principal = stripped
        rights, deny, inherited = _parse_rights(m.group(2))
        if not rights:
            continue
        aces.append(Ace(principal, rights, deny=deny, inherited=inherited))
    return aces


def list_aces(path):
    """返回 ``path`` 上的全部访问控制项（含继承来的）。"""
    return parse_aces(run(path), path)


def list_explicit_aces(path):
    """返回 ``path`` 上**显式设置**的访问控制项。

    从父目录继承来的项不算显式设置。
    """
    return [ace for ace in list_aces(path) if not ace.inherited]


def _is_windows():
    return sys.platform == "win32"


def _local_free(pointer):
    """释放 Win32 ``LocalAlloc`` 分配的内存。"""
    try:
        import ctypes

        ctypes.windll.kernel32.LocalFree(pointer)
    except Exception:  # pragma: no cover
        pass


def _lookup_sid_name(sid):
    """把 ``S-1-5-32-546`` 这样的 SID 解析成 ``BUILTIN\\Guests`` 这样的名字。"""
    if not _is_windows():
        return None
    try:
        import ctypes
        from ctypes import wintypes

        advapi32 = ctypes.windll.advapi32
        psid = ctypes.c_void_p()
        if not advapi32.ConvertStringSidToSidW(str(sid), ctypes.byref(psid)):
            return None
        try:
            name_len = wintypes.DWORD(0)
            domain_len = wintypes.DWORD(0)
            use = wintypes.DWORD(0)
            # 先用空缓冲区问出所需长度。
            advapi32.LookupAccountSidW(
                None,
                psid,
                None,
                ctypes.byref(name_len),
                None,
                ctypes.byref(domain_len),
                ctypes.byref(use),
            )
            if not name_len.value:
                return None
            name = ctypes.create_unicode_buffer(name_len.value)
            domain = ctypes.create_unicode_buffer(max(domain_len.value, 1))
            ok = advapi32.LookupAccountSidW(
                None,
                psid,
                name,
                ctypes.byref(name_len),
                domain,
                ctypes.byref(domain_len),
                ctypes.byref(use),
            )
            if not ok:
                return None
            if domain.value:
                return "%s\\%s" % (domain.value, name.value)
            return name.value
        finally:
            _local_free(psid)
    except Exception:  # pragma: no cover - 解析失败时退回字符串比较
        return None


def _lookup_name_sid(name):
    """把 ``BUILTIN\\Guests`` 这样的名字解析成 SID 字符串。"""
    if not _is_windows():
        return None
    try:
        import ctypes
        from ctypes import wintypes

        advapi32 = ctypes.windll.advapi32
        sid_len = wintypes.DWORD(0)
        domain_len = wintypes.DWORD(0)
        use = wintypes.DWORD(0)
        advapi32.LookupAccountNameW(
            None,
            str(name),
            None,
            ctypes.byref(sid_len),
            None,
            ctypes.byref(domain_len),
            ctypes.byref(use),
        )
        if not sid_len.value:
            return None
        sid = ctypes.create_string_buffer(sid_len.value)
        domain = ctypes.create_unicode_buffer(max(domain_len.value, 1))
        ok = advapi32.LookupAccountNameW(
            None,
            str(name),
            sid,
            ctypes.byref(sid_len),
            domain,
            ctypes.byref(domain_len),
            ctypes.byref(use),
        )
        if not ok:
            return None
        text = ctypes.c_wchar_p()
        if not advapi32.ConvertSidToStringSidW(sid, ctypes.byref(text)):
            return None
        try:
            return text.value
        finally:
            _local_free(text)
    except Exception:  # pragma: no cover - 解析失败时退回字符串比较
        return None


def _bare(principal):
    """去掉 icacls 接受的前导 ``*``，并统一大小写。"""
    text = str(principal).strip()
    while text.startswith("*"):
        text = text[1:].strip()
    return text.upper()


def principal_aliases(principal):
    """返回 ``principal`` 的全部等价写法（名字、SID，均为大写）。

    ``icacls`` 在写入时接受 SID（``*S-1-5-32-546``），回显时却给出账号名
    （``BUILTIN\\Guests``）；反之亦然。判定权限时必须把两者看成同一主体。
    """
    if principal is None:
        return frozenset()
    try:
        cached = _PRINCIPAL_CACHE.get(principal)
    except TypeError:  # pragma: no cover - 不可哈希的输入
        cached = None
    if cached is not None:
        return cached
    bare = _bare(principal)
    aliases = {bare}
    if bare:
        if _SID_RE.match(bare):
            name = _lookup_sid_name(bare)
            if name:
                aliases.add(_bare(name))
        else:
            sid = _lookup_name_sid(bare)
            if sid:
                aliases.add(_bare(sid))
    result = frozenset(aliases)
    if len(_PRINCIPAL_CACHE) < _PRINCIPAL_CACHE_LIMIT:
        try:
            _PRINCIPAL_CACHE[principal] = result
        except TypeError:  # pragma: no cover
            pass
    return result


def same_principal(left, right):
    """判断两个主体标识是否指向同一个安全主体。"""
    if left is None or right is None:
        return False
    if _bare(left) == _bare(right):
        return True
    return bool(principal_aliases(left) & principal_aliases(right))


def deny(path, principal, spec, recursive=False):
    """在 ``path`` 上为主体添加一条拒绝项。

    ``spec`` 是 icacls 的权限说明，例如 ``"(OI)(CI)(RX)"``。带上 ``(OI)(CI)``
    时该拒绝项会被子对象继承；``recursive`` 为真时用 ``/T`` 立即下发到整棵
    已有子树。
    """
    args = ["/deny", "%s:%s" % (principal, spec)]
    if recursive:
        args.append("/T")
    return run(path, *args)


def grant(path, principal, spec, recursive=False):
    """在 ``path`` 上为主体添加一条允许项。"""
    args = ["/grant", "%s:%s" % (principal, spec)]
    if recursive:
        args.append("/T")
    return run(path, *args)


def disable_inheritance(path):
    """移除 ``path`` 上从父目录继承来的项。"""
    return run(path, "/inheritance:r")

"""把构建产物发布到共享目录。"""

import os
import shutil

from .errors import ICaclsError
from .icacls import deny, grant, list_aces, list_explicit_aces, same_principal
from .rights import can_write

#: 只读发布时授给访问者的权限（对象继承 + 容器继承 + 读取执行）。
READONLY_SPEC = "(OI)(CI)(RX)"

#: 只读发布时拒绝访问者的权限（对象继承 + 容器继承 + 写入）。
#:
#: 只读靠的是「拒绝写」而不是「拒绝读」。这里的 ``(OI)(CI)`` 不能省：少了
#: 继承标记，发布之后新建的文件就完全不受限制。
WRITE_DENY_SPEC = "(OI)(CI)(W)"


def publish(src_dir, dst_dir, principal):
    """把 ``src_dir`` 发布到 ``dst_dir``。

    目标目录会被创建；``principal`` 在整个子树内只读：读取执行的权限与
    写入的拒绝项都下发到发布时已存在的每个目录与文件，并且都带继承标记，
    因此发布之后新建的条目同样受限。

    返回已发布的根目录。
    """
    shutil.copytree(src_dir, dst_dir, dirs_exist_ok=True)
    # 先把访问者需要的读权限摆好，再用拒绝项压住写权限。顺序不能反：拒绝
    # 写之后发布者自己可能连枚举子项的权限都没有了。
    _apply_to_subtree(grant, dst_dir, principal, READONLY_SPEC, deny_flag=False)
    _apply_to_subtree(deny, dst_dir, principal, WRITE_DENY_SPEC, deny_flag=True)
    return dst_dir


def _root_covered(path, principal, deny_flag):
    """``path`` 自身是否已经带上针对 ``principal`` 的显式访问控制项。"""
    for ace in list_aces(path):
        if ace.inherited or ace.deny != deny_flag:
            continue
        if same_principal(ace.principal, principal):
            return True
    return False


def _apply_to_subtree(op, path, principal, spec, deny_flag):
    """把访问控制项下发到 ``path`` 及其整棵子树。

    ``/T`` 负责覆盖发布时已经存在的条目，``spec`` 里的继承标记负责覆盖之后
    新建的条目。若递归下发在遍历子项时被系统拒绝（例如拒绝项覆盖了发布者
    自己，发布者因此失去枚举子项的权限），根目录上的可继承项其实已经生效，
    子项通过继承得到同样的限制，这时不该让整个发布失败。
    """
    try:
        return op(path, principal, spec, recursive=True)
    except ICaclsError:
        if _root_covered(path, principal, deny_flag):
            return ""
        return op(path, principal, spec)


def audit(dst_dir, principal):
    """返回 ``dst_dir`` 子树内 ``principal`` 仍可写入的路径列表。"""
    offenders = []
    for dirpath, dirnames, filenames in os.walk(dst_dir):
        for name in list(dirnames) + list(filenames):
            path = os.path.join(dirpath, name)
            if can_write(path, principal):
                offenders.append(path)
    return sorted(offenders)


def explicit_grants(path):
    """返回 ``path`` 上显式设置的允许项主体集合。"""
    return sorted({a.principal for a in list_explicit_aces(path) if not a.deny})


def all_principals(path):
    """返回 ``path`` 上出现过的全部主体。"""
    return sorted({a.principal for a in list_aces(path)})
